(n, m) = list(map(int, input().split()))
matrix = []
for i in range(n):
	row = list(map(int, input().split()))
	matrix.append(row)
res = [[0 for i in range(m)] for j in range(n)]
for i in range(n):
	for j in range(m):
		if (i + j) % 2:
			res[i][j] = 720720 + matrix[i][j] ** 4
		else:
			res[i][j] = 720720
		print(res[i][j], end=' ')
	print()
